        'msteams_blurb' => 'Сповіщення служби підтримки як картки у ваших каналах Teams - термінові заявки, порушення SLA, заявки для кожної команди - з кнопкою, що веде прямо до заявки.',
        'msteams_intro' => 'Публікуйте сповіщення служби підтримки в каналах Microsoft Teams як картки, кожна з кнопкою «Відкрити у FreeITSM». Позначте, про що має отримувати повідомлення кожен канал: термінові заявки, попередження та порушення SLA, заявки його команд, інциденти сторінки статусу, погодження, що очікують.',
        'msteams_not_ready' => 'Спершу виконайте Система → Перевірка бази даних: вона створює таблиці, у яких зберігаються ці сповіщення.',
        'msteams_bot_h' => 'Чат-бот Teams',
        'msteams_bot_body' => 'Ця сторінка лише публікує сповіщення. Щоб люди могли спілкуватися зі службою підтримки в Teams - кожна розмова стає заявкою - налаштуйте бота Teams у розділі Заявки → Налаштування → Обмін повідомленнями.',
        'msteams_bot_count' => 'Налаштовано каналів бота Teams: {n}.',
        'msteams_bot_link' => 'Відкрити налаштування обміну повідомленнями',
        'msteams_how_h' => 'Отримайте адресу вебхука каналу',
        'msteams_how_body' => 'У Teams відкрийте канал, натисніть … поруч із його назвою, потім Workflows. Виберіть «Post to a channel when a webhook request is received», виконайте кроки та скопіюйте адресу, яку отримаєте наприкінці. Вставте її нижче в канал. Адреса працює як пароль: будь-хто, хто її має, може публікувати в цьому каналі, тому вона зберігається зашифрованою і більше ніколи не показується.',
        'msteams_channels_h' => 'Канали',
