        'msteams_test_failed' => 'Teams не прийняв це: {detail}',
        'msteams_delete_confirm' => 'Видалити цей канал і процеси, які він створив? Їхня історія залишиться на сторінці «Процеси».',
        'msteams_needs_name' => 'Дайте каналу назву.',
        'threecx_blurb' => 'Бачте, хто дзвонить, ще до відповіді, зберігайте кожен дзвінок у заявці абонента й набирайте номер одним клацанням.',
        'threecx_intro' => 'Коли лунає дзвінок, 3CX запитує FreeITSM, кому належить номер, і показує ім\'я абонента - і відкриває аналітику його заявку. Коли дзвінок завершується, його позначають у цій заявці від імені аналітика, який відповів. Номери телефонів у заявках і в розділі «Люди» також можна набирати через 3CX.',
        'threecx_direction' => '3CX звертається до FreeITSM - FreeITSM ніколи не підключається до 3CX, тому йому не потрібні ні адреса вашої телефонної системи, ні пароль 3CX. Усе, що потрібно 3CX, є в шаблоні нижче.',
        'threecx_not_ready' => 'Спершу виконайте Система → Перевірка бази даних: вона створює таблицю, у якій ця інтеграція зберігає журнал дзвінків.',
        'threecx_connect' => 'Підключити 3CX',
        'threecx_connect_body' => '3CX підключається до FreeITSM через шаблон CRM. Створіть токен, завантажте шаблон і завантажте його в Admin Console 3CX у розділі Integrations → CRM. 3CX має мати змогу дістатися наведеної нижче адреси.',
        'threecx_endpoint' => 'Адреса FreeITSM, як її бачитиме 3CX',
        'threecx_reach_hint' => 'Спочатку це ваша публічна базова URL-адреса. 3CX часто працює в хмарі, тому це має бути адреса, доступна з інтернету. Змініть її тут, і завантаження оновиться відповідно.',
        'threecx_token' => 'Токен',
        'threecx_token_none' => 'Токена ще немає - створіть його, щоб увімкнути інтеграцію.',
        'threecx_token_make' => 'Створити',
        'threecx_token_rotate' => 'Замінити',
        'threecx_rotate_confirm' => 'Створити новий токен? 3CX перестане звертатися до FreeITSM, доки ви знову не завантажите шаблон (або не вставите в нього новий токен).',
        'threecx_copy' => 'Копіювати',
        'threecx_copied' => 'Скопійовано.',
        'threecx_download' => 'Завантажити',
        'threecx_download_body' => 'Шаблон, готовий до завантаження: адреса, цей токен, пошук абонента та звіт про дзвінок. Він містить токен, тому не передавайте файл нікому.',
        'threecx_download_needs_token' => 'Спершу створіть токен - шаблон містить його.',
        'threecx_calls_h' => 'Дзвінки в заявках',
