        'threecx_rule_log_only' => 'Жодної - дзвінки лише перелічено нижче',
        'threecx_rule_hint' => 'Заявка, яку 3CX відкриває аналітику, коли лунає дзвінок, підпорядковується тому самому вибору.',
        'threecx_create' => 'Відкривати нову заявку для дзвінка від того, хто не має відкритої заявки',
        'threecx_create_unknown' => 'Також для номерів, яких немає в жодної особи у FreeITSM',
        'threecx_create_hint' => 'Лише для вхідних дзвінків (прийнятих або пропущених). Призначається аналітик, який відповів на дзвінок. Невідомого абонента записують як «Caller» з його номером, щоб згодом пов\'язати з потрібною особою.',
        'threecx_fallback' => 'Писати нотатки від імені, коли користувач 3CX не є аналітиком',
        'threecx_fallback_hint' => 'Нотатку пише аналітик, електронна пошта якого збігається з користувачем 3CX, що відповів на дзвінок. Коли такого немає - секретар, спільний телефон - її пише натомість цей аналітик із зазначенням того, хто відповів. Якщо нікого не вибрано, такі дзвінки лише перелічено нижче.',
        'threecx_nobody' => 'Ніхто',
        'threecx_company' => 'Компанія для заявок із невідомих номерів',
        'threecx_company_hint' => 'Заявка відомого абонента потрапляє до його власної компанії.',
        'threecx_team' => 'Команда для нових заявок',
