        'threecx_none' => 'Немає',
        'threecx_dial_h' => 'Дзвінок одним клацанням',
        'threecx_dial_body' => 'Номери телефонів у заявках, у розділі Заявки → Користувачі та в розділі «Люди» отримують кнопку «Дзвонити», яка набирає номер через ваш телефон. Вона відкривається на власному комп\'ютері аналітика, де він уже ввійшов у 3CX, тож FreeITSM ніколи не потрібен його внутрішній номер.',
        'threecx_dial' => 'Адреса набору',
        'threecx_dial_hint' => 'Поставте {number} там, де має бути номер. Для вебклієнта 3CX: https://your-pbx.3cx.com/webclient/#/call?phone={number}. Для настільного застосунку 3CX (або будь-якого софтфона): tel:{number}. Залиште порожнім, щоб вимкнути кнопки «Дзвонити».',
        'threecx_saved' => 'Збережено.',
        'threecx_try' => 'Спробувати дзвінок',
        'threecx_try_body' => 'Подивіться, що зробив би дзвінок за цих налаштувань - хто абонент, до якої заявки він потрапить і від імені кого буде написана нотатка. Нічого не записується: це те саме рішення, яке приймає справжній дзвінок, лише описане.',
