        'tika_blurb' => 'Розпізнавайте текст у PDF, старіших файлах Office та сканованих документах, щоб їх можна було шукати.',
        'tika_intro' => 'Вказує FreeITSM на службу читання документів. Файли Word, Excel, PowerPoint і звичайний текст уже доступні для пошуку без цього; Tika додає формати, які FreeITSM не може прочитати самостійно.',
        'tika_security_title' => 'Не відкривайте доступ із мережі',
        'tika_security_body' => 'Tika не має пароля чи будь-якої автентифікації: усе, що може до неї достукатися, прочитає будь-який надісланий файл. Запускайте її так, щоб з нею міг спілкуватися лише цей сервер — прив\'язаною до 127.0.0.1 або в приватній мережі контейнерів — і ніколи не відкривайте її порт в інтернет.',
        'tika_connection' => 'З\'єднання',
        'tika_url_label' => 'Адреса',
        'tika_url_hint' => 'Наприклад, http://127.0.0.1:9998. Залиште порожнім, щоб вимкнути читання документів; PDF просто позначатимуться як нечитабельні.',
        'tika_timeout_label' => 'Час очікування (секунди)',
