        'tika_saved_off' => 'Збережено. Читання документів вимкнено.',
        'tika_requeued' => '{n} вкладень, які раніше не вдалося прочитати, додано до черги.',
        'tika_pending' => '{n} вкладень очікують на читання.',
        'tika_formats' => 'Що читається',
        'tika_without' => 'Уже читається без Tika',
        'tika_with' => 'Додає Tika',
        'tika_legacy_office' => 'Старіші файли Office (.doc, .xls, .ppt)',
        'tika_scanned' => 'Скановані документи та фотографії тексту — за допомогою розпізнавання символів',
        'tika_running' => 'Запуск власного екземпляра',
        'tika_running_body' => 'FreeITSM не встановлює Tika і не керує нею. Запустіть її самостійно, де вам зручно, і вкажіть її адресу вище. У Docker це одна команда:',
        'tika_image_note' => 'Використовуйте образ -full. Менший образ не має розпізнавання символів, тож скановані документи повертатимуться порожніми.',
        'slack_workspaces' => 'Робочі простори Slack',
        'slack_workspaces_desc' => 'Кожен із них — це застосунок Slack, який ви встановлюєте у власному робочому просторі. FreeITSM ніколи не бачить ваш трафік Slack — застосунок звертається напряму до цього сервера.',
        'slack_col_channel' => 'Відстежується',
        'slack_any_channel' => 'Будь-який канал, до якого його запрошено',
        'slack_empty' => 'Робочих просторів Slack ще немає. Додайте один, а потім отримайте його застосунок у Slack.',
        'slack_needs_setup' => 'Потребує налаштування',
        'slack_add_title' => 'Додати робочий простір Slack',
        'slack_edit_title' => 'Редагувати робочий простір Slack',
