        'slack_name_required' => 'Дайте цьому робочому простору назву.',
        'slack_unchanged' => 'Без змін — залиште порожнім, щоб зберегти поточне значення',
        'slack_bot_token' => 'OAuth-токен бота',
        'slack_bot_token_hint' => 'Із вашого застосунку Slack, у розділі OAuth &amp; Permissions. Починається з xoxb-. Ви отримаєте його після встановлення застосунку, тож при першому збереженні залиште поле порожнім.',
        'slack_signing_secret' => 'Секрет підпису',
        'slack_signing_secret_hint' => 'Із вашого застосунку Slack, у розділі Basic Information. Так FreeITSM підтверджує, що повідомлення справді надійшло зі Slack, тож нічого не приймається, доки це значення не встановлено.',
        'slack_watch_channel' => 'Відстежувати лише цей канал',
        'slack_watch_channel_hint' => 'Ідентифікатор каналу Slack, наприклад C08ABCDEF. Залиште порожнім, щоб створювати заявку з будь-якого каналу, куди запрошено застосунок — на активному каналі це означає заявку на кожне повідомлення, тож більшість вказує тут один канал підтримки.',
        'slack_company_shared' => 'Спільний — визначати за відправником',
        'slack_company_hint' => 'Закріпіть цей робочий простір за однією компанією або залиште його спільним і дозвольте відправнику вирішувати.',
        'slack_delete_confirm' => 'Видалити робочий простір Slack «{name}»? Заявки, вже створені з нього, збережуть свою історію; надходити перестануть лише нові повідомлення.',
        'slack_diag_title' => 'Перевірка стану Slack',
        'slack_diag_desc' => 'Перевіряє все, що може бути непомітно неправильним — не лише чи працює токен. Кожен результат підказує, що з цим робити.',
        'slack_diag_running' => 'Перевірка — це звернення до Slack і до вашої власної публічної адреси, тож зачекайте кілька секунд…',
        'slack_diag_rerun' => 'Запустити ще раз',
        'slack_diag_all_ok' => 'Усе гаразд. Повідомлення в каналі Slack, що відстежується, ставатимуть заявками, а відповіді повертатимуться в гілку обговорення.',
        'slack_diag_some_warn' => 'Працює, але є на що звернути увагу. Ніщо нижче не заважає надходженню заявок, але варто прочитати.',
