        'slack_copy_manifest' => 'Скопіювати маніфест',
        'slack_scopes_heading' => 'Що дозволено застосунку',
        'slack_scopes_desc' => 'Ваш адміністратор Slack побачить цей список під час затвердження застосунку. Ніщо тут не дозволяє йому створювати канали, запрошувати людей чи публікувати повідомлення там, куди його не запрошено.',
        'slack_step1' => 'У Slack перейдіть на <strong>api.slack.com/apps</strong> і оберіть <strong>Create New App → From a manifest</strong>. Виберіть робочий простір, у якому має бути служба підтримки.',
        'slack_step2' => 'Вставте цей маніфест. Він задає назву, права доступу та адресу, на яку Slack надсилає повідомлення, тож нічого не потрібно вмикати вручну.',
        'slack_step3' => 'Натисніть <strong>Install to Workspace</strong> і підтвердьте. Потім скопіюйте <strong>Bot User OAuth Token</strong> і <strong>Signing Secret</strong> сюди, у форму редагування — повторно Slack токен не покаже. <strong>Якщо Slack показує жовтий банер &ldquo;Reinstall to Workspace&rdquo;, спершу натисніть його</strong> — інакше токену бракуватиме більшості прав, і заявки надходитимуть без імені відправника.',
        'slack_step4' => 'Перевірте, що URL запиту нижче збігається з тим, що Slack показує в розділі <strong>Event Subscriptions</strong>. Slack перевіряє його одразу після збереження застосунку, тож цей сервер має бути доступний з інтернету.',
        'slack_step5' => 'У Slack запросіть застосунок до каналу, який має відстежуватися: <strong>/invite @YourApp</strong>. Він не може читати канал, до якого його не запрошено.',
