        'server_url_hint' => 'DAV-адреса сервера, а не його вебсторінка. Baïkal: <code>https://server/dav.php/</code> · Nextcloud: <code>https://server/remote.php/dav/</code> · Radicale: <code>https://server/</code>. Аналітики можуть обирати календарі лише на цьому сервері.',
        'caldav_auth' => 'Спосіб входу',
        'auth_auto' => 'Автоматично (рекомендовано)',
        'auth_digest' => 'Digest',
        'auth_basic' => 'Basic',
        'caldav_auth_hint' => 'Залиште значення «Автоматично», якщо у вас немає причин змінювати його. Стандартний Baïkal очікує Digest, а не Basic, і режим «Автоматично» сам запитує сервер, який спосіб той пропонує.',
        'caldav_probe' => 'Спробувати увійти (необов\'язково, використовується лише для цього тесту й не зберігається)',
