        'caldav_test_failed_hint' => 'Перевірте, що вказана адреса — це шлях DAV сервера, а не його вебсторінка, і що FreeITSM може достукатися до нього мережею.',
        'caldav_probe_ok' => '{user} увійшов і може записувати в: {list}.',
