        'caldav_no_notify' => 'Сервери CalDAV не надсилають сповіщення про зміни, тому зміни, внесені в календар, з\'являються лише після запуску запланованого завдання.',
        'people_desc_caldav' => 'Кожен аналітик входить на сервер CalDAV і обирає свій календар у розділі «Налаштування». Адміністратор не може обрати його за аналітика, оскільки лише в аналітика є пароль, яким можна туди потрапити.',
        'no_account' => 'Не увійшов',
        'switch_title' => 'Змінити, куди записує це з\'єднання?',
        'switch_confirm' => 'Це забере назад {mapped} подій(ю), які це з\'єднання додало в календарі аналітиків, і вимкне синхронізацію календаря для {pushing} аналітик(ів), які ним користуються, щоб кожен міг налаштувати її знову. Аналітиків на інших з\'єднаннях і посилання для підписки це не зачіпає.',
        'switch_ok' => 'Змінити',
        'switch_done' => 'Збережено. Синхронізацію календаря скинуто для аналітиків цього з\'єднання.',
        'perm_title' => 'Перш ніж це запрацює',
        'perm_body' => 'Реєстрації застосунку потрібен дозвіл <strong>Calendars.ReadWrite</strong> як <strong>Application</strong>-дозвіл (не Delegated — в Azure це окремі списки), зі схваленням адміністратора. Майте на увазі, що цей дозвіл дає FreeITSM змогу записувати в <strong>будь-яку поштову скриньку в клієнті (tenant)</strong>. Якщо це більше, ніж ви готові надати, обмежте застосунок групою безпеки з увімкненою поштою, що охоплює лише ваших аналітиків, за допомогою Application Access Policy в Exchange Online.',
        'name' => 'Назва',
        'source_mailbox' => 'Позичити облікові дані з поштової скриньки',
        'source_own' => 'Ввести облікові дані',
        'mailbox' => 'Поштова скринька',
        'no_mailboxes' => 'Жодна поштова скринька Microsoft у цій системі не має облікових даних Azure, які можна позичити, тож введіть їх нижче. Це нормально, якщо календарі ваших аналітиків перебувають в іншому клієнті (tenant), ніж поштові скриньки для прийому заявок, або якщо прийом заявок узагалі не через Microsoft.',
        'tenant_id' => 'ID каталогу (tenant)',
        'client_id' => 'ID застосунку (client)',
        'client_secret' => 'Секрет клієнта',
        'secret_note' => 'Секрет зберігається в зашифрованому вигляді й більше ніколи не показується. Залиште поле порожнім під час редагування, щоб зберегти вже наявний секрет.',
        'test' => 'Тест',
