        'probe_ok' => '{addr} має календар, у який FreeITSM може записувати.',
        'probe_bad' => 'Календар для {addr} не знайдено. Перевірте, що ця адреса — справжня поштова скринька в цьому клієнті (tenant): адреса електронної пошти аналітика у FreeITSM не завжди збігається з адресою його поштової скриньки.',
        'conn_delete_confirm' => 'Видалити «{name}»?',
        'conn_delete_title' => 'Видалити це з\'єднання?',
        'conn_delete_used' => 'FreeITSM забирає назад {mapped} подій(ю), які це з\'єднання додало в календарі аналітиків, і вимикає синхронізацію календаря для {pushing} аналітик(ів), які ним користуються. Аналітиків на інших з\'єднаннях це не зачіпає.',
        'conn_deleted' => 'З\'єднання видалено',
        'people_heading' => 'До якої поштової скриньки синхронізується кожен аналітик',
        'people_desc' => 'За замовчуванням FreeITSM використовує електронну адресу облікового запису аналітика, яка часто не збігається з його поштовою скринькою — наприклад, у разі локального облікового запису або імпорту з каталогу за іншим ключем. Тут це можна перевизначити. Аналітики обирають, <em>чи</em> синхронізувати їхню роботу; тільки адміністратор обирає, <em>куди</em> вона потрапляє.',
        'col_analyst' => 'Аналітик',
        'col_status' => 'Обрано аналітиком',
