        'tasks_note' => 'Цей аналітик вирішив включати свої завдання. Він обирає це самостійно в розділі «Налаштування»; тут це налаштувати за нього не можна.',
        'saved_unverified' => 'Збережено. Перевірити адресу не вдалося, оскільки з\'єднання не працює, — перевірте його вище.',
        'inbound_heading' => 'Зміни, внесені в календар',
        'inbound_desc' => 'Перемістіть одну з таких зустрічей в Outlook, і заявка переміститься слідом. Для цього потрібне запущене завдання <code>cron/calendar_sync_pull.php</code> — раз на 5 хвилин цілком підходить. Без нього синхронізація однобічна, і саме так вона наразі й працює.',
        'accept_deletes' => 'Видалення зустрічі знімає запланований час із заявки',
        'notify_url' => 'URL для сповіщень (необов\'язково)',
        'notify_url_note' => 'Залиште порожнім, щоб покладатися лише на заплановану перевірку, — це цілком нормально, зміни тоді надходять протягом кількох хвилин. Заповніть поле, і Microsoft повідомлятиме FreeITSM у момент кожної зміни, тож вона з\'явиться за секунди. Це має бути <strong>HTTPS-адреса, доступна для Microsoft з інтернету</strong>, що закінчується на <code>/api/calendar/graph_notify.php</code>. Заплановане завдання потрібне в будь-якому разі: воно поновлює підписки й підхоплює все, що інакше загубилося б через пропущене сповіщення.',
        'notify_suggest' => 'Використати цю адресу',
