        'health_stale_note' => 'Зміни, внесені в Outlook, надходять лише під час запуску запланованого завдання, тож зазвичай це означає, що воно зупинилося — перевірте, що <code>cron/calendar_sync_pull.php</code> усе ще виконується за розкладом. Саме воно й поновлює підписки, тож сповіщення припиняються через кілька днів після його зупинки. Якщо ви навмисно запускаєте його рідше, ніж раз на півгодини, це очікувано.',
