        'sub_none' => 'Не підписано',
        'sub_none_note' => 'Адресу для сповіщень задано, але Microsoft немає куди звертатися для цієї особи, тож її зміни надходять лише під час запуску запланованого завдання. Наступний запуск спробує створити підписку; якщо це й далі не вдаватиметься, причина з\'явиться тут.',
        'sub_lapsed' => 'Термін дії підписки минув',
        'accept_deletes_note' => 'За замовчуванням вимкнено. Якщо ввімкнути, аналітик, який видаляє таку зустріч на телефоні, застає заявку вже знятою із запланованого часу, коли сідає за роботу, — саме в цьому часто й полягає сенс. Кожна така зміна записується в історію заявки, а незвично велику кількість видалень за раз буде відхилено, а не виконано, оскільки це швидше схоже на збій, ніж на команду. Якщо вимкнено, видалена зустріч просто з\'явиться знову під час наступної зміни заявки.',
