        'selfreg_heading' => 'Самостійна реєстрація',
        'selfreg_desc' => 'Чи можуть люди самостійно створювати обліковий запис порталу самообслуговування зі сторінки входу. За замовчуванням вимкнено. Коли увімкнено, реєстрація все одно підтверджується посиланням у листі, перш ніж встановлюється пароль.',
