        'php_limits' => 'PHP на цьому сервері приймає завантаження з браузера до {upload} на файл і {post} на запит (upload_max_filesize і post_max_size у php.ini) та має {memory} пам\'яті для роботи. Файл, який PHP відхиляє, ніколи не потрапляє до FreeITSM, тож ліміт вище за ці значення допомагає лише для електронної пошти. Вебсервер або проксі перед ним (nginx client_max_body_size, IIS maxAllowedContentLength) може встановлювати власний нижчий ліміт.',
