        'jit_company_none' => 'Жодної, доки адміністратор не надасть доступ',
        'tab_groups' => 'Групи й команди',
        'tab_portal' => 'Портал і компанія',
        'claims_intro' => 'Необов\'язково. Використовуйте групи, які надсилає ваш провайдер ідентифікації, щоб визначати, хто може бути аналітиком, хто є адміністратором і до яких команд належать люди. Перевіряється заново при кожному вході, тож доступ відповідає провайдеру ідентифікації. Що може команда, налаштовується в Система → Команди.',
        'field_group_claim' => 'Звідки беруться групи',
        'field_group_claim_hint' => 'Частина даних входу, що містить список груп. Більшість провайдерів називають її groups; Keycloak використовує realm_access.roles. Можливо, провайдер потрібно налаштувати на її надсилання — див. довідку.',
        'claims_guide' => 'Покроковий посібник із налаштування',
