        'field_groups_seen' => 'Побачені групи',
        'field_groups_seen_hint' => 'Кожна група, яку цей провайдер надсилав під час входу. Деякі провайдери, як-от Microsoft, надсилають коди замість назв — дайте кожній назву тут, і випадні списки нижче показуватимуть назву. Код можна знайти поруч з назвою групи у вашого провайдера (у Microsoft Entra: Групи, потрібна група, Object ID).',
        'col_code' => 'Код',
        'col_group_name' => 'Назва',
        'col_last_seen' => 'Остання поява',
        'group_not_seen' => 'Ще ніхто не входив із цією групою — перевірте, що її написано точно так, як надсилає ваш провайдер.',
        'field_claim_analyst_group' => 'Група аналітиків',
        'field_claim_analyst_group_hint' => 'Лише люди з цієї групи можуть входити як аналітики, і лише вони створюються автоматично. Тому, хто її залишає, буде відмовлено при наступному вході. Залиште порожнім, щоб дозволити бути аналітиком будь-кому, кого впускає цей провайдер, як зараз.',
        'field_claim_admin_group' => 'Група адміністраторів',
        'field_claim_admin_group_hint' => 'Люди з цієї групи є адміністраторами; ті, кого в ній немає, — ні. Залиште порожнім, щоб керувати адміністраторами вручну. Останнього адміністратора ніколи не буде вилучено.',
        'field_group_teams' => 'Команди',
        'field_group_teams_hint' => 'При кожному вході людей додають до команд, на які вказують їхні групи, і вилучають із цих команд, коли вони залишають групу. Команди, яких тут немає, ніколи не змінюються. Аналітики, створені цим провайдером, отримують свої модулі від цих команд.',
