        'field_default_modules_hint' => 'Ключі модулів через кому, що надаються аналітикам, створеним через JIT (напр. {example}). {strong} — задайте це для пілотів, щоб автоматично створені аналітики не були адміністраторами.',
        'field_default_modules_strong' => 'Залиште порожнім — і вони отримають повний доступ до всіх модулів',
        'field_default_modules_placeholder' => 'tickets, knowledge',
        'field_company' => 'Компанія',
        'field_company_hint' => 'Якій компанії-клієнту належить цей постачальник ідентичності — її ініціатори спрямовуються сюди на порталі самообслуговування. Залиште Глобально для внутрішнього постачальника MSP (наприклад, входу аналітиків).',
        'field_company_global' => 'Глобально (внутрішній / усі)',
        'field_portal_domains' => 'Домени електронної пошти',
        'field_portal_domains_hint' => 'По одному в рядку, напр. company.com. На порталі адреса електронної пошти з одного з цих доменів одразу спрямовується до цього провайдера, навіть уперше. Це стосується й людей, які сьогодні входять із паролем. Усі інші бачать поле пароля, як зазвичай. Піддомен потребує окремого рядка. Залиште порожнім, щоб нікого не спрямовувати.',
        'cb_portal_show_button' => 'Показувати кнопку на вході в портал',
        'cb_portal_show_button_desc' => 'Зніміть позначку, щоб сторінка мала лише поле електронної пошти. Люди з наведених вище доменів усе одно потраплять до цього провайдера. Вхід для аналітиків це не зачіпає.',
