        'carddav_test_desc' => 'Перевіряє, чи FreeITSM може підключитися до сервера й увійти, і показує список адресних книг, які він бачить.',
        'carddav_test_desc_create' => 'Перевіряє, чи FreeITSM може підключитися до сервера й увійти з цими даними.',
        'carddav_test_next' => 'Збережіть це, а потім скористайтеся значком налаштувань у цьому рядку, щоб вибрати адресну книгу та які контакти імпортувати.',
        'carddav_page_sub' => 'Адресна книга CardDAV. Через неї ніхто не входить — вона переносить контакти у вашу службу підтримки.',
        'tab_contacts' => 'Контакти',
