        'carddav_pick_summary_none' => 'Поки нічого не вибрано.',
        'carddav_write_heading' => 'Надсилання змін назад',
        'carddav_write_hint' => 'Зазвичай FreeITSM лише читає цю адресну книгу. Увімкніть це, і зміна, яку аналітик вносить у посаду, відділ, офіс, телефон чи мобільний контакту, також записується в його картку. Табельний номер та керівник залишаються у FreeITSM, бо в картці контакту немає де їх зберігати.',
        'carddav_write_back' => 'Записувати зміни, зроблені у FreeITSM, назад в адресну книгу',
        'carddav_allow_create' => 'Дозволити аналітикам додавати людей до цієї адресної книги',
        'carddav_allow_create_hint' => 'Вимкнено за замовчуванням. Якщо увімкнено, особа, якої немає в жодній адресній книзі, отримує кнопку Додати до адресної книги в Заявках та Активах, яка створює тут її картку та прив\'язує її. Перш ніж щось записати, FreeITSM перевіряє, що в книзі ще немає нікого з такою адресою електронної пошти, а потім перевіряє, що нова картка потрапляє під імпорт цього джерела — додаючи тег чи групу, за якими воно імпортує, — і видаляє її знову, якщо ні.',
        'carddav_write_warning' => 'Змінюються лише перелічені вище дані, і лише для контакту, який редагується. Усе інше в картці — фото, нотатки, день народження, повна адреса, групи — залишається без змін. Якщо хтось уже змінив ту саму інформацію в адресній книзі з часу останнього імпорту FreeITSM, зміна відхиляється, а не перезаписує чужу.',
        'carddav_write_check' => 'Перевірити дозвіл',
        'carddav_write_checking' => 'Опитування сервера…',
        'carddav_write_check_failed' => 'Не вдалося завершити перевірку дозволу.',
