        'entra_sync_desc' => 'Створює й оновлює осіб з Entra ID, щоб вони існували до того, як хтось увійде. Нікого ніколи не видаляють: ті, хто йде, позначаються як такі, що пішли, а запуск, який раптом знаходить значно менше людей, зупиняється без жодних змін. Імпортовані особи можуть одразу входити через цього постачальника.',
