        'maint_page_title' => 'Імпортовані люди',
        'maint_page_sub' => 'Люди, яких імпортувало джерело каталогу - LDAP, адресна книга або Microsoft Entra ID, - коли щодо них потрібне рішення: їхнє джерело видалено, воно більше їх не імпортує або їх не слід було імпортувати. Нікого із заявками чи обладнанням не буде видалено, а все, що робиться тут, записується в системний журнал.',
