        'maint_stale_hint' => 'Кожен імпорт записує дату, коли востаннє знайшов кожну особу. Ці люди й досі призначені цьому джерелу, але воно не знаходило їх протягом обраного вами часу: їх могли видалити з каталогу, вивести з того, що імпортується, або імпорт міг перестати працювати. Позначте їх як звільнених, залиште як звичайних людей, якими це джерело більше не керує, або видаліть.',
        'maint_remove_heading' => 'Вилучити імпортованих людей',
