        'del_desc' => 'Наскільки наполегливо FreeITSM намагається доставити кожен вебхук.',
        'opt_default' => '{label} (за замовчуванням)',
        'del_attempts_label' => 'Спроб до відмови',
        'del_attempts_one' => '1 спроба (без повторів)',
        'del_attempts_opt' => 'Спроб: {n}',
        'del_attempts_help' => 'Невдала спроба повторюється через 1 хвилину, потім через 5 хвилин, 15 хвилин, 1 годину і 6 годин, далі кожні 6 годин. Після останньої спроби доставку буде позначено як <strong>Невдала</strong>, і вона чекатиме на <em>Повтор</em>. Зміна застосовується до вебхуків, поставлених у чергу відтепер - ті, що вже в черзі, зберігають число, з яким починали.',
        'del_timeout_label' => 'Очікування відповіді кінцевої точки',
        'del_timeout_opt' => '{n} с',
        'del_timeout_help' => 'Скільки кожна спроба чекає, перш ніж вважатися невдалою. Збільшуйте лише для кінцевої точки, про яку відомо, що вона повільна: обробник надсилає один вебхук за раз, тож тривале очікування затримує решту черги. <em>Надіслати тест</em> у редакторі процесів чекає щонайбільше 25 секунд.',
        'del_int_label' => 'Якщо надсилання перервано на півдорозі',
        'del_int_retry' => 'Спробувати ще раз - кінцева точка може отримати це двічі',
        'del_int_stop' => 'Зупинити й залишити для повтору',
        'del_int_help' => 'Якщо обробник зупинено посеред надсилання - перезапуск сервера або примусове завершення запланованого завдання - ніхто не знає, чи отримала кінцева точка дані. Через 10 хвилин FreeITSM це вирішує: <strong>Спробувати ще раз</strong> зараховує це як невдалу спробу й повторює за розкладом вище; <strong>Зупинити</strong> одразу позначає доставку як невдалу, щоб ви могли перевірити кінцеву точку й повторити самостійно. Кожне надсилання містить заголовок <code>X-FreeITSM-Delivery</code> з тим самим числом при кожній спробі й при повторі, тож отримувач, якого ви запускаєте самі, може ігнорувати дублікат. Чат-інструменти, як-от Slack і Teams, не можуть і показали б повідомлення двічі.',
        'dp_title' => 'Захист даних',
        'dp_desc' => 'Що FreeITSM зберігає на диску про ваші webhook і як довго.',
        'enc_on_title' => 'URL-адреси webhook і секрети підпису зашифровані при зберіганні',
        'enc_on_body' => 'Зберігаються з AES-256-GCM, і в процесі, і в черзі доставки. URL webhook сам по собі є обліковими даними &mdash; будь-хто, хто його має, може писати у ваш канал &mdash; а секрет підпису доводить, що повідомлення справді надійшло від вас.',
        'enc_off_title' => 'Ключ шифрування не налаштовано &mdash; URL-адреси webhook і секрети підпису зберігаються відкритим текстом',
        'enc_off_body' => 'FreeITSM шифрує їх, коли є файл ключа шифрування, але в цій інсталяції його немає, тож вони зберігаються як є, а не призводять до повної відмови ваших webhook. Будь-хто, хто може прочитати базу даних або її резервну копію, може писати у ваші канали та підробляти ваші підписи. Налаштуйте ключ шифрування (<code>ENCRYPTION_KEY_PATH</code>) і повторно збережіть кожен процес із webhook, щоб зашифрувати збережені значення.',
        'ret_label' => 'Зберігати надісланий вміст',
        'ret_none' => 'Не зберігати його взагалі',
        'ret_1' => '1 день',
        'ret_7' => '7 днів (рекомендовано)',
        'ret_30' => '30 днів',
        'ret_forever' => 'Доки існує запис про доставку',
        'ret_help' => 'Журнал доставок зберігає точний вміст, який було надіслано. У форматі <strong>Повний запис</strong> це <strong>ціла заявка</strong> &mdash; тема, заявник, усе &mdash; скопійована сюди відкритим текстом. Через стільки днів вміст запиту та тіла відповідей затираються, а <em>запис</em> про доставку (кінцева точка, статус, час, помилки) зберігається для аудиту, доки зберігання журналу вище ({days} дн.) не видалить рядок повністю.',
        'ret_tradeoff' => '<strong>Компроміс:</strong> <em>Повтор</em> надсилає збережений вміст ще раз, тож доставку, вміст якої затерто, повторити вже неможливо. Повтор зазвичай застосовують за години після збою, а не за тижні.',
        'ov_title' => 'Огляд',
        'ov_desc' => 'Стан доставок з першого погляду &mdash; останні 7 днів, а також ваші найактивніші кінцеві точки та процеси, що надсилають найбільше.',
