    'bingo' => [
        'heading' => 'Feature Bingo',
        'intro' => 'Більшість людей використовує лише частку того, що має. Кожна картка — це те, що вміє FreeITSM, і її зірка засвічується, щойно це налаштовано тут. Відкрийте картку, щоб побачити, що це, чому це варто робити і де це налаштувати. Усе, чим ви ніколи не користуватиметеся: позначте «Не для нас», і воно зникне з рахунку.',
