    'managers' => [
        'heading' => 'Керівники',
        'intro' => 'Керівник — це користувач порталу самообслуговування, який бачить заявки, створені людьми, якими він керує, наприклад, начальник відділу. У порталі він отримує вкладку <strong>Заявки команди</strong>. Служби підтримки це не стосується.',
        'needs_verify' => 'Спершу виконайте Система → Перевірка бази даних. Доки це не зроблено, керівники лишаються вимкненими незалежно від налаштувань тут, бо конфіденційні заявки неможливо буде відрізнити.',
        'on_heading' => 'Керівники в порталі',
        'enabled' => 'Дозволити керівникам бачити заявки своєї команди',
        'enabled_desc' => 'Вимкнено, доки ви не ввімкнете. Поки це вимкнено, жодне з наведених нижче налаштувань не діє.',
        'source_heading' => 'Звідки беруться керівники',
        'source_desc' => 'Два джерела одночасно. Лінії керівництва налаштовуються для кожного керівника кнопкою «Доступ керівника» в Заявки → Користувачі або Активи → Користувачі.',
        'directory' => 'Використовувати поле «Керівник» кожної особи',
        'directory_desc' => 'Той, кого вказано як Керівника людини — вручну або з вашого каталогу, — бачить її заявки.',
        'depth' => 'Наскільки глибоко',
        'depth_direct' => 'Люди, які підпорядковуються йому безпосередньо',
        'depth_all' => 'Усі нижче за нього, до самого низу',
        'can_heading' => 'Що можуть керівники',
        'can_desc' => 'Керівники завжди можуть читати заявки своєї команди. У кожній заявці їм повідомляється, що ще вони можуть робити.',
        'can_reply' => 'Відповідати на заявки своєї команди',
        'can_close' => 'Закривати заявки своєї команди',
        'conf_heading' => 'Конфіденційні заявки',
        'conf_desc' => 'Що керівник бачить у заявці, позначеній як конфіденційна, — діагноз, надісланий до HR, або скаргу на самого керівника.',
        'conf_none' => 'Нічого (рекомендовано)',
        'conf_none_desc' => 'Заявку повністю пропущено. Керівник навіть не здогадується, що вона існує.',
        'conf_stub' => 'Лише те, що конфіденційна заявка існує',
        'conf_stub_desc' => 'Показується як «Конфіденційна заявка» з номером і статусом, без жодного вмісту. Зауважте, що вже це може підказати керівнику, що хтось подав щось приватне.',
        'conf_all' => 'Усе',
        'conf_all_desc' => 'Конфіденційні заявки показуються як і будь-які інші. Обирайте це, лише якщо через цей портал ніколи не подають нічого конфіденційного.',
        'notify_heading' => 'Сповіщення керівників про нові заявки',
        'notify_desc' => 'Коли хтось із команди керівника створює заявку — але ніколи ту, яку керівнику не можна відкривати, наприклад конфіденційну.',
        'notify_none' => 'Не сповіщати (за замовчуванням)',
        'notify_none_desc' => 'Керівники бачать нові заявки, коли відкривають «Заявки команди».',
        'notify_email' => 'Надсилати листа',
        'notify_email_desc' => 'Лист із номером і темою заявки та посиланням на неї, який надсилається на адресу керівника зі скриньки заявок. Керівники без адреси нічого не отримують. Для посилання потрібна публічна веб-адреса (Заявки → Налаштування → Шаблони листів) — без неї заявка, що надійшла поштою, надсилає посилання, яке не працює.',
        'notify_bell' => 'У дзвіночку сповіщень порталу',
        'notify_bell_desc' => 'У дзвіночку, який є в кожного керівника в заголовку порталу, — такому самому, як в аналітиків. Тихіше за лист: він чекає, коли керівник наступного разу увійде.',
        'leavers_heading' => 'Люди, які пішли',
        'leavers' => 'Далі показувати заявки людей, які пішли',
        'leavers_desc' => 'Увімкнено за замовчуванням, тож заявка, що лишається відкритою після звільнення особи, зберігає нагляд. Керівник, який пішов, завжди втрачає доступ.',
        'edit_heading' => 'Хто може налаштовувати лінії керівництва',
        'edit_admins' => 'Лише адміністратори',
        'edit_people' => 'Аналітики, які можуть редагувати людей',
        'edit_desc' => 'Надання доступу керівника дозволяє читати заявки інших людей, тому його варто обмежити кількома особами.',
        'saved' => 'Збережено',
        'save_failed' => 'Не вдалося зберегти: {error}',
        'overview_heading' => 'Керівники',
        'overview_desc' => 'Усі, хто кимось керує, з кількістю людей, яких вони бачать, — розраховано так, ніби керівників увімкнено, щоб ви могли перевірити перед увімкненням.',
