    'self_service' => [
        'heading' => 'Портал самообслуговування',
        'intro' => 'Який вигляд має портал для людей, які створюють заявки, і що він їм дозволяє. Для більшості організацій портал — єдина частина FreeITSM, яку взагалі бачить клієнт, тож саме цей екран варто брендувати окремо від решти.',
        'appearance_heading' => 'Вигляд',
        'appearance_desc' => 'Це стосується лише порталу. Логотип у розділі <strong>Система &rarr; Брендинг</strong> і далі використовується для застосунку, екрана входу та ваших листів.',
        'logo_label' => 'Логотип порталу',
        'logo_desc' => 'Окремий логотип для порталу &mdash; корисно, коли служба підтримки працює під іншою назвою або коли основний логотип малювали для темної шапки застосунку і на світлій сторінці він виглядає недоречно. Залиште порожнім, щоб використовувати основний логотип.',
        'logo_remove' => 'Видалити',
